def attach_particle(word: str, particle: str) -> str:
    # Final-sound info: (has_batchim, is_rieul)
    DIGIT_END = {
        '0': (True, False),   # 영 ends in ㅇ
        '1': (True, True),    # 일 ends in ㄹ
        '2': (False, False),  # 이
        '3': (True, False),   # 삼 ends in ㅁ
        '4': (False, False),  # 사
        '5': (False, False),  # 오
        '6': (True, False),   # 육 ends in ㄱ
        '7': (True, True),    # 칠 ends in ㄹ
        '8': (True, True),    # 팔 ends in ㄹ
        '9': (False, False),  # 구
    }
    # Group units (position >= 4): 만, 억, 조, 경
    GROUP_END = {1: (True, False),   # 만 ㄴ
                 2: (True, False),   # 억 ㄱ
                 3: (False, False),  # 조 ㅗ
                 4: (False, False)}  # 경 ㅕ
    # Within-group units: 십 (pos1), 백 (pos2), 천 (pos3)
    POS_END = {1: (True, False), 2: (True, False), 3: (True, False)}

    def final_info(w):
        # Trailing digit run
        i = len(w)
        while i > 0 and w[i - 1].isdigit():
            i -= 1
        if i < len(w):
            digits = w[i:]
            n = int(digits)
            if n == 0:
                return DIGIT_END['0']
            s = str(n)
            # position of the lowest nonzero digit, counted from the right
            p = None
            for k, ch in enumerate(reversed(s)):
                if ch != '0':
                    p = k
                    break
            if p == 0:
                return DIGIT_END[s[-1]]
            if p < 4:
                return POS_END[p]
            g = p // 4
            if g in GROUP_END:
                return GROUP_END[g]
            return (False, False)
        # Hangul syllable
        code = ord(w[-1]) - 0xAC00
        if code < 0 or code > 11171:
            return (False, False)
        jong = code % 28
        if jong == 0:
            return (False, False)
        return (True, jong == 8)  # index 8 is ㄹ

    has_batchim, is_rieul = final_info(word)

    if particle == "은/는":
        suffix = "은" if has_batchim else "는"
    elif particle == "이/가":
        suffix = "이" if has_batchim else "가"
    elif particle == "을/를":
        suffix = "을" if has_batchim else "를"
    elif particle == "과/와":
        suffix = "과" if has_batchim else "와"
    elif particle == "으로/로":
        suffix = "으로" if (has_batchim and not is_rieul) else "로"
    else:
        raise ValueError("unknown particle: " + particle)

    return word + suffix
